signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "reason": {
      "type": "string",
      "description": "Reason ID selected by the user from the 'getShortLeaveApprovalList' API."
    },
    "comment": {
      "type": "string",
      "description": "Optional comment provided by the user explaining the short leave."
    },
    "approverNumber": {
      "type": "string",
      "description": "Approver's employee ID, selected from the 'getShortLeaveApprovalList' API. ex:- '000001'"
    },
    "leaveDate": {
      "type": "string",
      "description": "Leave date in the format DD-MM-YYYY"
    },
    "startTime": {
      "type": "string",
      "pattern": "^\\d{2}\\.\\d{2}$",
      "description": "Start time in 'HH.MM' 24-hour format. Example: '01.00'."
    },
    "Year": {
      "type": "string",
      "description": "takes from the user year like 2025"
    },
    "endTime": {
      "type": "string",
      "pattern": "^\\d{2}\\.\\d{2}$",
      "description": "End time in 'HH.MM' 24-hour format. Example: '09.00'."
    }
  },
  "required": [
    "reason",
    "approverNumber",
    "leaveDate",
    "startTime",
    "endTime",
    "Year"
  ]
}

basic.transformer:
(async function(data, args, reqOptions) {
  const applyshortleave = await BeaconBar.executeFunction('shortleave')(args) 
  return applyshortleave;
})

